package nl.smartstreamlabs.sbwdroneconfig;
import com.mojang.blaze3d.vertex.*;import net.minecraft.client.renderer.*;
/** Reuses the established rigid GPU batching; one geometry bake, original meshes retained. */
public final class Mpl01Renderer extends com.atsuishio.superbwarfare.client.renderer.entity.VehicleRenderer<Mpl01Entity> implements FastMeshRenderer<Mpl01Entity>{
 private Adv01Gpu.Batch batch;private Pm01Entity payload;
 public Mpl01Renderer(net.minecraft.client.renderer.entity.EntityRendererProvider.Context c){super(c,new Mpl01Model());shadowRadius=2.6f;}
 @Override public void vehicleAxis(Mpl01Entity e,PoseStack p,float yaw,float partial){var m=e.getVehicleTransform(partial);var at=m.transformPosition(new org.joml.Vector3d()).sub(e.getPosition(partial).x,e.getPosition(partial).y,e.getPosition(partial).z);p.translate(at.x,at.y,at.z);p.mulPose(m.getUnnormalizedRotation(new org.joml.Quaterniond()).get(new org.joml.Quaternionf()));}
 @Override protected void applyRotations(Mpl01Entity e,PoseStack p,float age,float yaw,float partial,float scale){}
 @Override public RenderType getRenderType(Mpl01Entity e,net.minecraft.resources.ResourceLocation t,MultiBufferSource b,float partial){return RenderType.entityCutoutNoCull(Mpl01Materials.get(t).opaque());}
 @Override public void renderCube(PoseStack p,software.bernie.geckolib.cache.object.GeoCube c,VertexConsumer v,int light,int overlay,int color){if(batch!=null){batch.pose(c,p);return;}FastMeshRenderer.super.renderCube(p,c,v,light,overlay,color);}
 @Override public void actuallyRender(PoseStack p,Mpl01Entity e,software.bernie.geckolib.cache.object.BakedGeoModel model,RenderType type,MultiBufferSource buffers,VertexConsumer consumer,boolean rerender,float partial,int light,int overlay,int color){var previous=batch;var current=!rerender&&type!=null&&(buffers instanceof MultiBufferSource.BufferSource&&consumer instanceof BufferBuilder||WhiteHotRender.gpuSource(buffers))?Adv01Gpu.batch(model):null;batch=current;if(current!=null)current.begin();try{super.actuallyRender(p,e,model,type,buffers,consumer,rerender,partial,light,overlay,color);if(current!=null){WhiteHotRender.captureGpu(buffers,current,type,((color>>>24)&255)/255f);current.draw(type,light,overlay,((color>>16)&255)/255f,((color>>8)&255)/255f,(color&255)/255f,((color>>>24)&255)/255f);if(!rerender){var glass=VehicleGlassRenderTypes.glass(Mpl01Materials.get(getTextureLocation(e)).glass());WhiteHotRender.captureGpu(buffers,current,glass,((color>>>24)&255)/255f);current.draw(glass,light,overlay,((color>>16)&255)/255f,((color>>8)&255)/255f,(color&255)/255f,((color>>>24)&255)/255f);}}else if(!rerender&&type!=null){var glass=VehicleGlassRenderTypes.glass(Mpl01Materials.get(getTextureLocation(e)).glass());super.actuallyRender(p,e,model,glass,buffers,buffers.getBuffer(glass),true,partial,light,overlay,color);}}finally{batch=previous;}}
 @Override public void render(Mpl01Entity e,float yaw,float partial,PoseStack p,MultiBufferSource buffers,int light){super.render(e,yaw,partial,p,buffers,light);if(e.ammoMask()==0)return;if(payload==null||payload.level()!=e.level())payload=AddonEntities.PM01.get().create(e.level());if(payload==null)return;var origin=e.getPosition(partial);var forward=e.launchDirection(partial);payload.setYRot(Mpl01Frames.yaw(forward));payload.yRotO=payload.getYRot();payload.setXRot(Mpl01Frames.pitch(forward));payload.xRotO=payload.getXRot();for(int i=0;i<4;i++)if((e.ammoMask()&(1<<i))!=0){var at=e.mount(i,partial).subtract(origin);p.pushPose();p.translate(at.x,at.y,at.z);net.minecraft.client.Minecraft.getInstance().getEntityRenderDispatcher().getRenderer(payload).render(payload,payload.getYRot(),partial,p,buffers,light);p.popPose();}}
}
